namespace Challenge;public interface ICodeSource{string Next();}public interface ILinkStore{bool TryAdd(string code,string url);string? Get(string code);}public sealed class LinkService(ILinkStore store,ICodeSource codes){public string Create(string url){if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||(uri.Scheme!="http"&&uri.Scheme!="https"))throw new ArgumentException("Invalid URL",nameof(url));for(int i=0;i<100;i++){var c=codes.Next();if(!string.IsNullOrWhiteSpace(c)&&store.TryAdd(c,url))return c;}throw new InvalidOperationException("Could not allocate code");}public string? Resolve(string code)=>store.Get(code);}public sealed class MemoryLinkStore:ILinkStore{readonly Dictionary<string,string>d=new();readonly object gate=new();public bool TryAdd(string c,string u){lock(gate){return d.TryAdd(c,u);}}public string? Get(string c){lock(gate){return d.GetValueOrDefault(c);}}}
